// Valida el webhook de avisos que envía Campus Pulse: firma HMAC-SHA256, antigüedad y forma de los datos.
// Campus Pulse decide a quién avisar y qué decir; este flujo solo entrega el aviso (hoy por correo).
const crypto = require('crypto');
const TOLERANCIA_SEGUNDOS = 300;
const CORREO = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

const rechazar = (motivo) => [{ json: { valido: false, motivo } }];

const secreto = $env.N8N_SECRETO;
if (!secreto) return rechazar('El secreto N8N_SECRETO no está configurado en n8n.');

const cabeceras = $input.first().json.headers ?? {};
const firma = cabeceras['x-pulse-firma'];
const marca = cabeceras['x-pulse-timestamp'];
if (!firma || !marca) return rechazar('Faltan las cabeceras de firma.');

// La firma se calcula sobre el cuerpo EXACTO que se envió (por eso el webhook guarda el cuerpo crudo).
let crudo;
try {
  crudo = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (error) {
  return rechazar('No llegó el cuerpo de la petición.');
}

const esperada = Buffer.from('sha256=' + crypto.createHmac('sha256', secreto).update(`${marca}.${crudo}`).digest('hex'));
const recibida = Buffer.from(String(firma));
if (esperada.length !== recibida.length || !crypto.timingSafeEqual(esperada, recibida)) return rechazar('Firma inválida.');

const edad = Math.abs(Math.floor(Date.now() / 1000) - Number(marca));
if (!Number.isFinite(edad) || edad > TOLERANCIA_SEGUNDOS) return rechazar('El mensaje es demasiado viejo o viene del futuro.');

let datos;
try { datos = JSON.parse(crudo); } catch (error) { return rechazar('El cuerpo no es JSON.'); }
const a = datos?.aviso;
if (datos?.evento !== 'aviso.reserva' || !CORREO.test(a?.correo ?? '') || typeof a?.asunto !== 'string' || typeof a?.mensaje !== 'string') {
  return rechazar('Los datos del aviso no tienen el formato esperado.');
}
return [{ json: { valido: true, aviso: { correo: a.correo, nombre: String(a.nombre ?? ''), asunto: a.asunto.slice(0, 150), mensaje: a.mensaje.slice(0, 2000) } } }];

